<?php
require dirname(__DIR__).'/includes/bootstrap.php'; require_permission('purchases.manage'); $bid=current_branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); try{db()->beginTransaction(); $items=[];$subtotal=0; foreach($_POST['product_id']??[] as $i=>$pid){$pid=(int)$pid;$qty=(float)($_POST['quantity'][$i]??0);$cost=(float)($_POST['unit_cost'][$i]??0); if($pid&&$qty>0){$line=$qty*$cost;$subtotal+=$line;$items[]=[$pid,$qty,$cost,$line];}} if(!$items) throw new RuntimeException('Add at least one item.'); $paid=(float)($_POST['paid_amount']??0); $status=$paid<=0?'unpaid':($paid+0.01>=$subtotal?'paid':'partial'); $no=next_code('PUR','purchases','purchase_no'); q('INSERT INTO purchases(branch_id,purchase_no,supplier_id,invoice_number,purchase_date,subtotal,paid_amount,payment_status,status,received_by,notes,created_at) VALUES(?,?,?,?,?,?,?,?,"received",?,?,NOW())',[$bid,$no,(int)($_POST['supplier_id']??0)?:null,trim($_POST['invoice_number']??''),$_POST['purchase_date'],$subtotal,$paid,$status,$_SESSION['user_id'],trim($_POST['notes']??'')]); $purchaseId=(int)db()->lastInsertId(); foreach($items as $it){q('INSERT INTO purchase_items(purchase_id,product_id,quantity,unit_cost,line_total) VALUES(?,?,?,?,?)',[$purchaseId,$it[0],$it[1],$it[2],$it[3]]); stock_move($bid,$it[0],$it[1],'purchase','purchase',$purchaseId,'Purchase received'); q('UPDATE products SET buying_price=? WHERE id=? AND branch_id=?',[$it[2],$it[0],$bid]);} if($paid>0 && (int)($_POST['supplier_id']??0))q('INSERT INTO supplier_payments(branch_id,supplier_id,purchase_id,amount,payment_method,reference_no,payment_date,created_by,created_at) VALUES(?,?,?,?,?,?,?, ?,NOW())',[$bid,(int)$_POST['supplier_id'],$purchaseId,$paid,$_POST['payment_method']??'cash',trim($_POST['reference_no']??''),$_POST['purchase_date'],$_SESSION['user_id']]); audit('create','purchases',$purchaseId); log_activity('Stock purchase received '.$no,'stock',$bid); db()->commit(); flash('success','Purchase received and stock updated.'); }catch(Throwable $e){if(db()->inTransaction())db()->rollBack(); flash('error',$e->getMessage());} redirect('modules/purchases.php');}
$rows=all('SELECT p.*,s.name supplier FROM purchases p LEFT JOIN suppliers s ON s.id=p.supplier_id WHERE p.branch_id=? ORDER BY p.id DESC LIMIT 200',[$bid]); $title='Stock Purchases'; $subtitle='Receive stock from suppliers and update inventory automatically.'; include dirname(__DIR__).'/includes/header.php'; ?>
<div class="toolbar"><a class="btn" href="?new=1">+ New Purchase</a><a class="btn light" href="inventory.php">Inventory</a></div><?php if(isset($_GET['new'])):?><section class="card"><h2>Receive Purchase</h2><form method="post"><?=csrf_field()?><div class="form-grid"><div class="form-group"><label>Supplier</label><select name="supplier_id"><option value="">No supplier</option><?php foreach(supplier_options() as $id=>$l):?><option value="<?=e($id)?>"><?=e($l)?></option><?php endforeach;?></select></div><div class="form-group"><label>Purchase Date</label><input type="date" name="purchase_date" required value="<?=e(today())?>"></div><div class="form-group"><label>Invoice Number</label><input name="invoice_number"></div><div class="form-group"><label>Paid Amount</label><input type="number" step="0.01" name="paid_amount" value="0"></div><div class="form-group"><label>Payment Method</label><select name="payment_method"><?php foreach(payment_methods() as $m=>$l): if($m==='gift_card')continue;?><option value="<?=e($m)?>"><?=e($l)?></option><?php endforeach;?></select></div><div class="form-group"><label>Reference</label><input name="reference_no"></div><div class="form-group full"><label>Notes</label><textarea name="notes"></textarea></div></div><h3>Items</h3><div id="lines"><div class="cart-row"><select name="product_id[]"><option value="">Product</option><?php foreach(product_options() as $id=>$l):?><option value="<?=e($id)?>"><?=e($l)?></option><?php endforeach;?></select><input type="number" step="0.01" name="quantity[]" placeholder="Qty"><input type="number" step="0.01" name="unit_cost[]" placeholder="Cost"><button type="button" class="btn small danger" onclick="this.parentElement.remove()">×</button></div></div><button type="button" class="btn secondary" onclick="addLine()">+ Add Item</button> <button class="btn">Receive Stock</button></form></section><script>function addLine(){document.querySelector('#lines').insertAdjacentHTML('beforeend',`<div class="cart-row"><select name="product_id[]"><option value="">Product</option><?php foreach(product_options() as $id=>$l):?><option value="<?=e($id)?>"><?=e($l)?></option><?php endforeach;?></select><input type="number" step="0.01" name="quantity[]" placeholder="Qty"><input type="number" step="0.01" name="unit_cost[]" placeholder="Cost"><button type="button" class="btn small danger" onclick="this.parentElement.remove()">×</button></div>`)}</script><?php endif;?><div class="table-wrap"><table><thead><tr><th>Date</th><th>No.</th><th>Supplier</th><th>Invoice</th><th>Total</th><th>Paid</th><th>Status</th><th>Items</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['purchase_date'])?></td><td><?=e($r['purchase_no'])?></td><td><?=e($r['supplier'])?></td><td><?=e($r['invoice_number'])?></td><td><?=money($r['subtotal'])?></td><td><?=money($r['paid_amount'])?></td><td><?=e($r['payment_status'])?></td><td><a class="btn small light" href="purchase_view.php?id=<?=e($r['id'])?>">View</a></td></tr><?php endforeach;?></tbody></table></div><?php include dirname(__DIR__).'/includes/footer.php'; ?>